import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import vm from 'node:vm';
import {intakeContext,startRequirements} from '../../reda-2/patient-start.mjs';
import {suggestionContext,planChoices} from '../../reda-2/plan-authoring-model.mjs';
const ctx={console};ctx.window=ctx;vm.createContext(ctx);for(const f of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','exercise-quality.js','core.js','planner.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);
test('patient start distinguishes contact needs from clinical context',()=>{assert.equal(startRequirements({name:'Fictional'},intakeContext()).length,3);const p={name:'Fictional',focus:'Vänster knä',goal:'Promenera'};assert.equal(startRequirements(p,intakeContext(),'clinic').length,0);assert.equal(startRequirements(p,intakeContext(),'digital').length,1);assert.equal(startRequirements({...p,email:'fictional@example.test'},intakeContext()).length,0)});
test('a visible start profile completes missing selectors without overriding a confirmed prescription',()=>{const c=suggestionContext(intakeContext('home'),{stage:'protected',capacity:'supported',trainingHistory:'',blueprintId:'knee_pf'});assert.equal(c.stage,'protected');assert.equal(c.capacity,'supported');assert.equal(c.trainingHistory,'regular');assert.equal(c.blueprintId,'knee_pf')});
test('one selected direction yields three distinct, bounded plans for the same patient context',()=>{const c={...intakeContext('home'),blueprintId:'knee_pf',goal:'Fictional goal'};const choices=planChoices(ctx.RedaPlanner,c);assert.equal(choices.length,3);assert.equal(new Set(choices.map(x=>JSON.stringify(x.plan.exercises))).size,3);for(const x of choices){assert.equal(x.plan.context.blueprintId,'knee_pf');assert.equal(x.plan.goal,'Fictional goal');assert.ok(x.plan.exercises.length>=2);assert.equal(x.plan.progressionDraft,undefined)}assert.ok(choices[1].plan.exercises.length<choices[0].plan.exercises.length);assert.ok(choices[2].plan.exercises.every(x=>x.dose.sets===1));assert.ok(choices[0].plan.exercises.some(x=>x.dose.sets>1));assert.throws(()=>planChoices(ctx.RedaPlanner,intakeContext()),/klinisk riktning/)});
